H = 5
W = 5
S = np.arange(H * W)
G = np.array([0, H * W - 1])
A_dom = np.array([0, 1, 2, 3])
coord_actions = np.array([[-1, 0], [+1, 0], [0, -1], [0, +1]])
maze = np.zeros(H * W)

@jax.jit
def Tr(s, a, s_):
    x, y = s % W, s // W
    next_coords = np.array([x, y]) + coord_actions[a]
    next_state = (
        + 1 * np.clip(next_coords[0], 0, W - 1)
        + W * np.clip(next_coords[1], 0, H - 1)
    )
    return (
        + 1.0 * ((maze[next_state] == 0) & (next_state == s_))
        + 1.0 * ((maze[next_state] == 1) & (s == s_))
    )

@jax.jit
def R(s, a, g):
    return 1.0 * (s == g) - 0.1

@jax.jit
def is_terminating(s, g):
    return s == g

@cache
@memo
def Q_mdp[s: S, a: A_dom, g: G](t):
    alice: knows(s, a, g)
    alice: given(s_ in S, wpp=Tr(s, a, s_))
    alice: chooses(a_ in A_dom, to_maximize=0.0 if t < 0 else Q_mdp[s_, a_, g](t - 1))
    return E[
        R(s, a, g) + (0.0 if t < 0 else
                      0.0 if is_terminating(s, g) else
                      1.0 * Q_mdp[alice.s_, alice.a_, g](t - 1))
    ]

@memo
def invplan[s: S, a: A_dom, g: G](t):
    observer: knows(a, s, g)
    observer: thinks[
        alice: chooses(g in G, wpp=1),
        alice: knows(s),
        alice: chooses(a in A_dom, wpp=exp(2 * Q_mdp[s, a, g](t))),
    ]
    observer: observes [alice.a] is a
    return observer[E[alice.g == g]]

